local config = {
  ui_story_31650101_1_dialog_content = "Bu, aku sudah memutuskan. Suatu hari, saya akan membangun mecha dinamis yang dirancang Kakek!",
  ui_story_31650101_2_dialog_content = "Itu bagus, Ciel. Ingat keputusan Anda dan belajarlah dengan giat!",
  ui_story_31650101_3_dialog_content = "Baiklah!",
  ui_story_31650101_4_dialog_content = "Saya sudah merencanakan semuanya, setelah saya membuat mecha, saya akan membantu semua orang melakukan banyak hal!",
  ui_story_31650101_5_dialog_content = "Oh? Apa yang paling ingin kamu lakukan?",
  ui_story_31650101_6_dialog_content = "Hmm... pengen...",
  ui_story_31650101_7_dialog_content = "Mengaktifkan mecha dinamis Styx.",
  ui_story_31650101_8_dialog_content = "Terhubung.",
  ui_story_31650101_9_dialog_content = "Mesin, diperiksa.",
  ui_story_31650101_10_dialog_content = "Sambungan tangan, diperiksa.",
  ui_story_31650101_11_dialog_content = "Sambungan kaki, diperiksa.",
  ui_story_31650101_12_dialog_content = "Tes operasi pelindung mobil, diperiksa.",
  ui_story_31650101_13_dialog_content = "Ciel, apakah Anda merasa tidak nyaman? Terutama di mana mecha terhubung ke kaki Anda.",
  ui_story_31650101_14_dialog_content = "Tidak, semuanya baik-baik saja.",
  ui_story_31650101_15_dialog_content = "Pemindaian tubuh selesai. Pengujian unit knalpot selesai. Pengujian bor selesai.",
  ui_story_31650101_16_dialog_content = "Mulai pengujian pertempuran.",
  ui_story_31650101_17_dialog_content = "Proyeksi target dalam jarak pertempuran.",
  ui_story_31650101_18_dialog_content = "Aku mengerti.",
  ui_story_31650101_19_dialog_content = "Graah...",
  ui_story_31650101_20_dialog_content = "Target telah sepenuhnya dibungkam; semuanya baik-baik saja. Ciel, kamu bisa turun sekarang.",
  ui_story_31650101_21_dialog_content = "Apa katamu?",
  ui_story_31650101_22_dialog_content = "Pengujian rutin dari Styx mecha dinamis satu orang.",
  ui_story_31650101_23_dialog_content = "Apa sebenarnya mekanisme ini?",
  ui_story_31650101_24_dialog_content = "Itu dapat membawa berbagai senjata dan memiliki mode rahasia yang kuat terkait dengan mobilitas.",
  ui_story_31650101_25_dialog_content = "Ini dapat memainkan peran penting dalam perang frontal dan gerilya.",
  ui_story_31650101_26_dialog_content = "Betulkah? Lalu bukankah itu berarti Illumina bisa—",
  ui_story_31650101_27_dialog_content = "Sayangnya, saat ini tidak dapat diproduksi secara massal atau digunakan dalam pertempuran resmi.",
  ui_story_31650101_28_dialog_content = "Prajurit rata-rata tidak memiliki cukup Lumina untuk melakukan manuver dengan lancar.",
  ui_story_31650101_29_dialog_content = "Pada saat yang sama, itu juga tidak cocok untuk Aurorian yang kuat karena mecha dapat membatasi penggunaan Luminatics.",
  ui_story_31650101_30_dialog_content = "Ya, agak memalukan untuk mengakuinya tapi...",
  ui_story_31650101_31_dialog_content = "Ini benar-benar hanya untuk orang-orang seperti saya yang kesulitan berjalan dan memiliki Lumina rata-rata.",
  ui_story_31650101_32_dialog_content = "Ah...",
  ui_story_31650101_33_dialog_content = "Hmm... Hei!",
  ui_story_31650101_34_dialog_content = "Aduh! Kenapa kau menusukku?!",
  ui_story_31650101_35_dialog_content = "<size=30>Ciel sedikit kesal. Anda harus pergi menghiburnya.</size>",
  ui_story_31650101_36_dialog_content = "<size=30>Eh? kenapa aku...</size>",
  ui_story_31650101_37_dialog_content = "<size=30>Hehe, karena kekhawatirannya ada hubungannya denganmu.</size>",
  ui_story_31650101_38_dialog_content = "Yah, harus lari. Selamat bersenang-senang! Sampai jumpa nanti!",
  ui_story_31650101_39_dialog_content = "T-Hati-hati... Ah, dia sudah menghilang.",
  ui_story_31650101_40_dialog_content = "Ahem, yah, menurutku mechamu luar biasa dan cantik!",
  ui_story_31650101_40X_dialog_content = "Jadi... semangat!",
  ui_story_31650101_41_dialog_content = "Aku tahu semua itu, tapi terima kasih sudah menghiburku...",
  ui_story_31650101_42_dialog_content = "Ugh, jika saja sesuatu yang tidak biasa akan terjadi sehingga saya bisa membuktikan nilai Styx untuk semua orang.",
  ui_story_31650101_43_dialog_content = "Sesuatu yang tidak biasa?",
  ui_story_31650101_44_dialog_content = "Sebenarnya, saya punya beberapa ide dan rencana untuk meningkatkan Styx generasi berikutnya.",
  ui_story_31650101_45_dialog_content = "Saya ingin PlayerName mendengarkan dan memberi saya beberapa saran.",
  ui_story_31650101_46_dialog_content = "Oh begitu. Anda ingin pendapat saya.",
  ui_story_31650101_47_dialog_content = "Jadi, apa rencanamu?",
  ui_story_31650101_48_dialog_content = "Anda bersedia mendengarkan? Luar biasa!",
  ui_story_31650101_49_dialog_content = "Nama rencananya adalah Penanaman Pohon Cepat Mecha. L-Biarkan aku membacakannya untukmu...",
  ui_story_31650101_49X_dialog_content = "Penanaman Pohon Cepat Mecha",
  ui_story_31650101_50_dialog_content = "Ahem, untuk menunjukkan rasa terima kasih kepada PlayerName dan Vice, Ciel melanjutkan misi penanaman pohon.",
  ui_story_31650101_51_dialog_content = "Dia mengemudikan mecha dan menuju Eraveil dengan PlayerName di belakangnya, tetapi dalam perjalanan...",
  ui_story_31650101_52_dialog_content = "Dia mengaktifkan mode rahasia dan berlari di atas permukaan laut dengan PlayerName di atas bahunya.",
  ui_story_31650101_53_dialog_content = "Mereka bertemu Eclipsites, tetapi berhasil kabur.",
  ui_story_31650101_54_dialog_content = "Ketika Ciel mencapai tujuannya, dia menggunakan bor untuk menggali lubang di tanah dan mulai menanam pohon.",
  ui_story_31650101_55_dialog_content = "Um, dan hanya itu, hanya tiga hal itu.",
  ui_story_31650101_56_dialog_content = "Apa rencana tak percaya yang baru saja kudengar?",
  ui_story_31650101_57_dialog_content = "Anda ingin melakukan apa dengan mecha? Bawa aku melewati bahumu dan kemudian meluncur ke langit?!",
  ui_story_31650101_58_dialog_content = "PlayerName, c-tenanglah. Jika Anda tidak menyukai rencana ini ...",
  ui_story_31650101_59_dialog_content = "C-Ce... Aku punya rencana lain!",
  ui_story_31650101_60_dialog_content = "Oke oke, saya akan santai, dan Anda juga harus. Lanjutkan.",
  ui_story_31650101_61_dialog_content = "Paket kedua disebut Belanja Aman Mecha.",
  ui_story_31650101_62_dialog_content = "Oh? Boleh juga. Dan aman.",
  ui_story_31650101_62X_dialog_content = "Belanja Aman Mecha",
  ui_story_31650101_63_dialog_content = "Untuk mengungkapkan rasa terima kasihnya, Ciel mengemudikan mecha dan pergi berbelanja dengan PlayerName.",
  ui_story_31650101_64_dialog_content = "Dalam perjalanan...",
  ui_story_31650101_65_dialog_content = "Dia pergi ke pasar di tepi laut dengan PlayerName di atas bahunya.",
  ui_story_31650101_66_dialog_content = "Di sana, dia membantu seorang lelaki tua yang pingsan di pinggir jalan.",
  ui_story_31650101_67_dialog_content = "Dia mengaktifkan mode rahasia dan memberi pencuri jalanan rasa bagaimana rasanya ditangkap secara berurutan.",
  ui_story_31650101_68_dialog_content = "Um, dan hanya itu, hanya tiga hal itu.",
  ui_story_31650101_69_dialog_content = "Itu terdengar lebih seperti hal-hal yang ingin Anda lakukan sendiri saat berada di mecha.",
  ui_story_31650101_70_dialog_content = "Mengapa Anda begitu terpaku pada gagasan menggendong saya di atas bahu Anda?",
  ui_story_31650101_71_dialog_content = "Ada banyak gosip tentangmu yang beredar di sekitar Illumina. Aku mendengar bahwa selama pertempuran legendaris itu...",
  ui_story_31650101_72_dialog_content = "Hampir semua Aurorian kuat Illumina memilih untuk berjuang untuk melindungi Caelestite.",
  ui_story_31650101_73_dialog_content = "Itu semua sangat mendebarkan, dan di pundak mereka yang lebar...",
  ui_story_31650101_74_dialog_content = "Ya, baiklah, kita bisa berhenti di situ. Saya sudah tahu itu, mereka membawa saya melalui itu semua.",
  ui_story_31650101_75_dialog_content = "Jadi begitulah Anda sampai pada kesimpulan bahwa untuk membuktikan kegunaan Styx, saya perlu digendong?",
  ui_story_31650101_76_dialog_content = "Ya.",
  ui_story_31650101_77_dialog_content = "Gores itu. Daripada menggendongku, lebih baik kau membantu orang lain membawa makanan atau sesuatu...",
  ui_story_31650101_78_dialog_content = "Oke. Maaf... tapi kamu juga harus mendengarkan rencana ketigaku.",
  ui_story_31650101_79_dialog_content = "Beri tahu saya pemikiran Anda sehingga saya dapat menggunakannya sebagai referensi saat saya menyesuaikan rencana saya.",
  ui_story_31650101_80_dialog_content = "Oke, saya siap menjadi kritikus.",
  ui_story_31650101_81_dialog_content = "Ahem... rencana ketigaku bernama Mecha's Island Survival.",
  ui_story_31650101_82_dialog_content = "Jadi sepertinya rencana ini melibatkan membawaku ke suatu tempat yang tidak masuk akal, ya?",
  ui_story_31650101_81X_dialog_content = "Kelangsungan Hidup Pulau Mecha",
  ui_story_31650101_83_dialog_content = "Karena rasa terima kasih, Ciel dan PlayerName bekerja sama di dermaga.",
  ui_story_31650101_84_dialog_content = "PlayerName ditarik ke arah laut dan secara tidak sengaja jatuh di atas pagar sambil menikmati pemandangan.",
  ui_story_31650101_85_dialog_content = "Jadi, dalam rencana ini, saya seorang pekerja tidak kompeten yang jatuh di atas pagar?",
  ui_story_31650101_86_dialog_content = "I-Ini hanya karakterisasi sementara demi rencana. Omong-omong...",
  ui_story_31650101_87_dialog_content = "Ciel mengaktifkan mode rahasia Styx untuk menyelamatkan PlayerName.",
  ui_story_31650101_88_dialog_content = "Itu lagi?",
  ui_story_31650101_89_dialog_content = "Mecha lepas landas dengan kecepatan kilat, meraih PlayerName di pinggang.",
  ui_story_31650101_90_dialog_content = "Itu akan mematahkan tulangku!",
  ui_story_31650101_91_dialog_content = "Keduanya jatuh ke laut dan kemudian... terdampar di pulau terpencil!",
  ui_story_31650101_92_dialog_content = "Itu pasti salah satu cara paling memutar untuk sampai ke pulau terpencil yang pernah ada.",
  ui_story_31650101_93_dialog_content = "Untuk bertahan hidup di pulau...",
  ui_story_31650101_94_dialog_content = "Saya mengemudikan mecha untuk memetik kelapa.",
  ui_story_31650101_95_dialog_content = "Saya mengemudikan mecha untuk menebang pohon menjadi kayu gelondongan dan membuat tempat perlindungan darurat.",
  ui_story_31650101_96_dialog_content = "Saya mengaktifkan mode rahasia dan berlari melintasi laut dengan PlayerName di bahu saya, akhirnya kembali ke darat.",
  ui_story_31650101_97_dialog_content = "Um, dan hanya itu, hanya tiga hal itu.",
  ui_story_31650101_98_dialog_content = "...",
  ui_story_31650101_99_dialog_content = "Kau serius?",
  ui_story_31650101_100_dialog_content = "Semua rencana ini berputar di sekitar membawa saya dalam beberapa cara dan mengaktifkan beberapa mode rahasia!",
  ui_story_31650101_101_dialog_content = "Dan kau begitu terobsesi dengan angka tiga, kau bahkan membuat tiga rencana...",
  ui_story_31650101_102_dialog_content = "I-Apakah itu masalah?",
  ui_story_31650101_103_dialog_content = "Tidak ada yang bisa dibandingkan ketika Anda hanya memiliki satu rencana, terlalu banyak untuk dibandingkan ketika Anda memiliki dua...",
  ui_story_31650101_104_dialog_content = "Jadi saya pikir tiga paket akan menawarkan keseimbangan yang sempurna dan memberi Anda lebih banyak pilihan.",
  ui_story_31650101_105_dialog_content = "Ketika kami melakukan tes sebelumnya, Petugas Gronru mengatakan itu akan baik-baik saja.",
  ui_story_31650101_106_dialog_content = "Saya tidak yakin ini yang dia maksud ...",
  ui_story_31650101_107_dialog_content = "Tidak. Petugas Gronru berarti mode rahasia dapat diaktifkan secara normal.",
  ui_story_31650101_108_dialog_content = "Saya berasumsi Anda akan tertarik dengan mecha saya dan ingin mencobanya.",
  ui_story_31650101_109_dialog_content = "Tapi saya pikir Anda tidak ingin saya menyentuhnya?",
  ui_story_31650101_110_dialog_content = "Bukankah Anda mengatakan sebelumnya, \"Ini masih prototipe yang belum selesai. Jangan menyentuhnya!\"",
  ui_story_31650101_111_dialog_content = "Beresiko untuk menyentuhnya, tetapi disetel hari ini, dan saya mengoperasikannya.",
  ui_story_31650101_112_dialog_content = "J-Jadi, apakah Anda ingin bergabung dengan saya dan Styx untuk...",
  ui_story_31650101_113_option_content = "Baik-baik saja maka. Kemana kita harus pergi?",
  ui_story_31650101_114_dialog_content = "K-Kamu setuju begitu cepat!",
  ui_story_31650101_115_dialog_content = "Meskipun aku belum memberitahumu apa yang kita lakukan?",
  ui_story_31650101_116_dialog_content = "Maksudku, kau jelas membuat banyak rencana. Kita bisa pergi dengan salah satu dari mereka.",
  ui_story_31650101_117_dialog_content = "Betulkah? Kalau begitu mari kita lakukan petualangan bawah laut yang mendebarkan. Mecha saya bisa—",
  ui_story_31650101_118_dialog_content = "Ah, a-jangan lakukan itu...",
  ui_story_31650101_119_option_content = "Biar kupikirkan dulu.",
  ui_story_31650101_120_dialog_content = "Tapi... tapi aku belum mengatakan apa yang akan kita lakukan.",
  ui_story_31650101_121_dialog_content = "Maksudku, aku bisa menebak berdasarkan rencana yang kau ceritakan padaku.",
  ui_story_31650101_122_dialog_content = "Semacam petualangan yang mendebarkan bagi saya, saya bayangkan.",
  ui_story_31650101_123_dialog_content = "Anda tidak suka petualangan yang mendebarkan? Saya pikir Anda akan menyukai mereka ...",
  ui_story_31650101_124_dialog_content = "Saya lebih suka duduk di sini dengan tenang dan melihat laut daripada melakukan petualangan yang mendebarkan.",
  ui_story_31650101_125_dialog_content = "Perhatikan laut?",
  ui_story_31650101_126_dialog_content = "Ya. Kami jarang mengunjungi kota-kota pesisir, jadi saya hanya melihat sekilas pemandangan itu dari jendela sesekali.",
  ui_story_31650101_127_dialog_content = "Anda benar-benar ingin melihat laut?",
  ui_story_31650101_128_dialog_content = "Tentu. Bukankah kamu terus membesarkan laut sebelumnya? Jadi...",
  ui_story_31650101_129_dialog_content = "Tunggu sebentar!",
  ui_story_31650101_130_dialog_content = "PlayerName, palka Colossus terbuka. Kita bisa segera berangkat!",
  ui_story_31650101_131_dialog_content = "Datang ke sini!",
  ui_story_31650101_132_dialog_content = "K-Kenapa kamu tiba-tiba memakai jas mechmu? Di mana saya harus duduk? Kemana kita akan pergi?",
  ui_story_31650101_133_dialog_content = "Sini, duduk di tangan Styx! Saya telah memasang sabuk pengaman!",
  ui_story_31650101_134_dialog_content = "Apa?!",
  ui_story_31650101_135_dialog_content = "Nama kode mecha dinamis: Styx",
  ui_story_31650101_136_dialog_content = "Tes dinamis: Normal",
  ui_story_31650101_137_dialog_content = "Sistem operasi kedalaman: Terhubung",
  ui_story_31650101_138_dialog_content = "Konfirmasi lokasi target: Koordinat yang ditentukan \"Permukaan Laut 1\"",
  ui_story_31650101_139_dialog_content = "Mode rahasia: Diaktifkan",
  ui_story_31650101_140_dialog_content = "Waktu hingga peluncuran: 3 detik",
  ui_story_31650101_141_dialog_content = "3",
  ui_story_31650101_142_dialog_content = "2",
  ui_story_31650101_143_dialog_content = "1",
  ui_story_31650101_144_dialog_content = "Meluncurkan",
  ui_story_31650101_145_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_31650101_146_dialog_content = "PlayerName, lihat! Kita berada di tengah laut. Ah, itu sangat luas!",
  ui_story_31650101_147_dialog_content = "Whoa... Angin laut yang asin!",
  ui_story_31650101_148_dialog_content = "Air lautnya sangat dingin! Ombak merendam kakiku!",
  ui_story_31650101_149_dialog_content = "Oh maafkan saya. Aku akan mengangkatmu lebih tinggi.",
  ui_story_31650101_150_dialog_content = "Ini seperti duduk di atas karang...",
  ui_story_31650101_151_dialog_content = "Apakah aman menyimpan mecha Anda terendam air?",
  ui_story_31650101_152_dialog_content = "Tentu. Saat pertama kali bertemu, Styx sedang bekerja di laut.",
  ui_story_31650101_153_dialog_content = "Memang. Semua orang terkejut ketika itu diangkat.",
  ui_story_31650101_154_dialog_content = "Saya sebenarnya sering mengemudikan Styx dan melayang di atas laut.",
  ui_story_31650101_155_dialog_content = "Dan saya selalu berpikir, jika saja saya bisa berbagi pemandangan di sini dengan... dengan...",
  ui_story_31650101_156_dialog_content = "<size=30>Teman baruku...</size>",
  ui_story_31650101_157_dialog_content = "Hmm? Apa katamu? Ombaknya cukup kencang.",
  ui_story_31650101_158_dialog_content = "Saya hanya ingin berbagi ini dengan Anda!",
  ui_story_31650101_159_dialog_content = "Jadi, setelah berpikir dan berpikir, saya memutuskan... untuk mengundang Anda.",
  ui_story_31650101_160_dialog_content = "Ini adalah apa yang Anda benar-benar ingin lakukan? Anda bisa saja memberitahu saya dari awal.",
  ui_story_31650101_161_dialog_content = "Saya tidak begitu tahu bagaimana menghadapi orang, jadi saya lebih suka membuat rencana...",
  ui_story_31650101_162_dialog_content = "PlayerName, a-apa pendapat Anda tentang pengalaman ini?",
  ui_story_31650101_163_dialog_content = "Hm... bagus.",
  ui_story_31650101_164_dialog_content = "Perasaan duduk di unit mech dan diluncurkan ke udara tidak seburuk yang saya bayangkan.",
  ui_story_31650101_165_dialog_content = "Saya tidak memiliki keluhan sama sekali, selain fakta bahwa apa yang saya duduki agak dingin dan keras ...",
  ui_story_31650101_166_dialog_content = "Mungkin saya harus menambahkan beberapa aksesori baru ke telapak tangan mecha, seperti bantal lembut?",
  ui_story_31650101_167_dialog_content = "Ah, aku hanya bercanda. Saya ragu tangan mecha dinamis ini dimaksudkan untuk diduduki.",
  ui_story_31650101_168_dialog_content = "Hmm... tapi aku masih akan menambahkan bantal!",
  ui_story_31650601_1_dialog_content = "<color=#e8d9bb>Splish, splash—</color>",
  ui_story_31650601_2_option_content = "Force Boost!",
  ui_story_31650601_3_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_31650601_4_dialog_content = "<color=#e8d9bb>\"Percobaan ke-104 gagal. Tidak dapat terhubung ke terminal target. Pastikan informasi kontak benar dan coba lagi...\"</color>",
  ui_story_31650601_5_dialog_content = "Jadi, masih belum bisa menghubungi siapa pun? *uhuk* Jika ini terus berlanjut...",
  ui_story_31650601_6_dialog_content = "<color=#e8d9bb>\"Sistem pemanas dimatikan.\"</color>",
  ui_story_31650601_7_dialog_content = "Achoo! Jika perhitungan saya benar, seharusnya masih ada cukup tenaga untuk menjalankan Styx satu kali...",
  ui_story_31650601_8_dialog_content = "\"Ubah lengan ke mode bor,\" \"Tingkatkan pelepasan daya menjadi 100%!\"",
  ui_story_31650601_9_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_31650601_10_dialog_content = "Berhasil?! Kamu tahu kamu bisa melakukannya, Styx!",
  ui_story_31650601_11_dialog_content = "<color=#e8d9bb>Boom! Bip—</color>",
  ui_story_31650601_12_dialog_content = "\"Styx?\" \"Styx!\"",
  ui_story_31650601_13_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_31650601_14_dialog_content = "Sekarang hanya aku... Achoo!",
  ui_story_31650601_15_dialog_content = "Suhu di bawah tanah beku dan batas-batasku semuanya menyimpulkan...",
  ui_story_31650601_16_dialog_content = "Aku takkan bertahan lama.",
  ui_story_31650601_17_dialog_content = "Tunggu, masih ada variabel yang belum diperhitungkan—<color=#FFFB400>bantuan dari luar.</color>",
  ui_story_31650601_18_dialog_content = "T-tapi...",
  ui_story_31650601_19_dialog_content = "Hai, semua, saya Ciel, ketua proyek penggalian tanah beku ini.",
  ui_story_31650601_20_dialog_content = "Chief? Bukankah kamu terlalu muda untuk menjadi seorang chief?",
  ui_story_31650601_21_dialog_content = "Berhenti. Saya yakin mereka punya alasan tersendiri mengirimnya.",
  ui_story_31650601_22_dialog_content = "Tugasnya cukup tinggi kali ini. Menurut tradisi kita, bukankah seharusnya chief memulai kami dengan sebuah lagu?",
  ui_story_31650601_23_dialog_content = "Chief, Chief, Chief!",
  ui_story_31650601_24_dialog_content = "Apa? Tapi aku... Aku... Kenapa kita tidak langsung kerja saja?",
  ui_story_31650601_25_dialog_content = "Karena aku tidak suka berbicara di depan umum, aku memilih untuk menugaskan mereka tugas-tugas seperti robot dan menghindari kontak yang tidak perlu...",
  ui_story_31650601_26_dialog_content = "Kepala suku seperti itu pasti tidak populer.",
  ui_story_31650601_27_dialog_content = "Saya pikir saya membuat cukup banyak kemajuan setelah bertemu PlayerName dengan Petugas Gronru...",
  ui_story_31650601_28_dialog_content = "Yah, saya tidak berhasil. Saya tidak hanya gagal berteman dengan tim, saya bahkan menjadi pemimpin yang buruk.",
  ui_story_31650601_29_dialog_content = "Kalau saja aku merasakan masalah sebelumnya, tim ini tak akan dalam bahaya.",
  ui_story_31650601_30_dialog_content = "Untungnya, saya tinggal di belakang dan mengulur waktu cukup lama untuk mereka keluar saat gua runtuh.",
  ui_story_31650601_31_dialog_content = "Kalau salah satu dari mereka yang terjebak di sini, aku nggak tahu harus berbuat apa.",
  ui_story_31650601_32_dialog_content = "Sekarang aku berpikir tentang itu, mungkin terjebak di gua lebih menghibur daripada jika aku hanya berhasil keluar sendirian.",
  ui_story_31650601_33_dialog_content = "Aku sama sekali tak bisa bergerak, tak ada yang bisa diajak bicara, hanya bergumam pada diri sendiri...",
  ui_story_31650601_34_dialog_content = "Tapi tidak apa-apa, karena aku sudah terbiasa sekarang...",
  ui_story_31650601_35_dialog_content = "Bip, bip, bip...",
  ui_story_31650601_36_dialog_content = "Mungkin seharusnya aku sudah mati dalam ledakan mecha itu beberapa tahun lalu...",
  ui_story_31650601_37_dialog_content = "Jadi, tidak ada keluhan jika aku mati di sini...",
  ui_story_31650601_38_dialog_content = "Bip, bip, bip, bip...",
  ui_story_31650601_39_dialog_content = "Bagaimana kabar Ciel sekarang?",
  ui_story_31650601_40_dialog_content = "Sigh, sama saja. Tak ada perubahan dan tak mau bicara.",
  ui_story_31650601_41_dialog_content = "Bangun, Ciel. Aku tahu kamu pura-pura tidur! Tidak sadarkah kamu sudah di tempat tidur selama setahun sekarang?",
  ui_story_31650601_42_dialog_content = "Permainan ini belum berakhir! Itu hanya cegukan. Kita selalu bisa memulai ulang.",
  ui_story_31650601_43_dialog_content = "Kamu masih sanggup untuk satu putaran lagi, kan? Buka matamu dan jawab aku!",
  ui_story_31650601_44_dialog_content = "Petugas Gronru, dan...",
  ui_story_31650601_45_dialog_content = "... dan PlayerName... Apakah aku tidak akan pernah melihatnya lagi?",
  ui_story_31650601_46_dialog_content = "Tak pernah menyangka akan berakhir seperti ini... Sungguh pil pahit untuk ditelan.",
  ui_story_31650601_47_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_31650601_48_dialog_content = "Ciel... Kepala! Bisakah kamu mendengarku?",
  ui_story_31650601_49_dialog_content = "Ya... Aku bisa mendengarmu!",
  ui_story_31650601_50_dialog_content = "Senang akhirnya mendengar kabar darimu, Chief!",
  ui_story_31650601_51_dialog_content = "Kami akan segera turun untuk menjemputmu...",
  ui_story_31650601_52_dialog_content = "Tolong jangan, itu terlalu berbahaya! Batuk, batuk...",
  ui_story_31650601_53_dialog_content = "<color=#e8d9bb>Bip — Bip — Bip —</color>",
  ui_story_31650601_54_dialog_content = "Sinyal terputus lagi...",
  ui_story_31650601_55_dialog_content = "Berdasarkan semua variabel, kemungkinan operasi penyelamatan yang berhasil adalah...",
  ui_story_31650601_56_option_content = "Berhenti!",
  ui_story_31650601_57_dialog_content = "Berhenti menghitung peluang! Meskipun hanya ada satu persen kesempatan, kami akan seratus persen membantu kamu keluar dari sana!",
  ui_story_31650601_58_dialog_content = "Namun…",
  ui_story_31650601_59_dialog_content = "Tidak ada tapi! Runtuhnya adalah kecelakaan yang aneh dan tidak ada hubungannya dengan keputusanmu!",
  ui_story_31650601_60_dialog_content = "Jadi berhentilah menyalahkan diri sendiri, tetap tegar dan tunggu kami!",
  ui_story_31650601_61_dialog_content = "Anda akan melakukan itu untuk saya...?",
  ui_story_31650601_62_dialog_content = "Atau mungkin aku mengigau karena kedinginan...",
  ui_story_31650601_63_dialog_content = "Suara itu yang terdengar di sistem komunikasi...",
  ui_story_31650601_64_dialog_content = "Anggota tim yang mana itu?",
  ui_story_31650601_65_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian</color>",
  ui_story_31650601_66_dialog_content = "<size=45><color=#e8d9bb>Duarr!!!</color></size>",
  ui_story_31650601_67_dialog_content = "Ciel!",
  ui_story_31650601_68_dialog_content = "Aku... di sini...",
  ui_story_31650601_69_dialog_content = "Akhirnya ketemu!",
  ui_story_31650601_70_dialog_content = "O-Officer Gronru? Apa yang Anda lakukan di sini secara langsung...",
  ui_story_31650601_71_dialog_content = "Saya sedang bertugas dukungan teknis di Undercity terdekat ketika mendengar ada kecelakaan, jadi saya bergegas ke sini.",
  ui_story_31650601_72_dialog_content = "Kamu membuatku sangat ketakutan. Aku pikir Ciel-ku yang kecil telah mengorbankan dirinya di ladang es untuk Illumina...",
  ui_story_31650601_73_dialog_content = "Maaf membuat kamu menunggu. Badai salju sedang turun, jadi kami menghabiskan banyak waktu dalam kondisi buruk untuk membuat jalan masuk.",
  ui_story_31650601_74_dialog_content = "Untungnya, matahari akhirnya terbit hari ini dan kita akhirnya bisa melanjutkan! Kamu tidak kedinginan sampai kehilangan akal, kan?",
  ui_story_31650601_75_dialog_content = "Terima kasih, Petugas Gronru, tapi saya baik-baik saja.",
  ui_story_31650601_76_dialog_content = "Kami semua lega melihat Chief baik-baik saja!",
  ui_story_31650601_77_dialog_content = "Kalian... Sebenarnya, aku bertahan berkat dorongan dari kalian melalui komunikasi ini.",
  ui_story_31650601_78_dialog_content = "Aku ingin mengatakan kepada kalian semua... Terima kasih! Dan juga... Maaf!",
  ui_story_31650601_79_dialog_content = "Tidak hanya aku tidak melakukan tugas sebagai kepala, kamu juga harus datang untuk menyelamatkanku...",
  ui_story_31650601_80_dialog_content = "Jangan bilang begitu! Kepala Ciel adalah teknisi yang paling tenang dan profesional yang pernah kami temui, dan kami sangat mempercayai Anda!",
  ui_story_31650601_81_dialog_content = "Belum lagi kalau bukan karena kamu, kita semua mungkin sudah terkubur di sana!",
  ui_story_31650601_82_dialog_content = "Namun, kami tidak pernah bisa menghubungimu melalui komunikasi...",
  ui_story_31650601_83_dialog_content = "Apa? Jadi siapa yang menyemangatiku...?",
  ui_story_31650601_84_dialog_content = "Nah, sepertinya PlayerName telah melakukan beberapa pekerjaan di balik layar lagi.",
  ui_story_31650601_85_dialog_content = "Kedengarannya seperti saya melakukan sesuatu yang buruk dari cara kamu mengatakannya.",
  ui_story_31650601_86_dialog_content = "PlayerName juga ada di sini?!",
  ui_story_31650601_87_dialog_content = "Ini adalah keadaan darurat, jadi saya harus meminta PlayerName untuk memberikan tumpangan dengan Colossus demi penyelamatan.",
  ui_story_31650601_88_dialog_content = "Jadi selama ini PlayerName yang selalu menenangkan aku...",
  ui_story_31650601_89_dialog_content = "Aku malu kamu harus melihat betapa paniknya aku!",
  ui_story_31650601_90_option_content = "Kamu seharusnya tidak!",
  ui_story_31650601_91_dialog_content = "Mengorbankan diri demi keselamatan orang lain tidak pernah menjadi hal yang patut untuk malu!",
  ui_story_31650601_92_dialog_content = "Dan aku pikir cara kamu bicara pada diri sendiri saat terjebak itu lucu.",
  ui_story_31650601_93_option_content = "Tidak apa-apa!",
  ui_story_31650601_94_dialog_content = "Wajar saja berbicara pada diri sendiri saat terjebak sendirian di bawah tanah.",
  ui_story_31650601_95_dialog_content = "Aku bahkan tidak ingin membayangkan apa yang akan kulakukan saat itu tanpa Soroz untuk menemaniku.",
  ui_story_31650601_96_dialog_content = "Tunggu, kamu dengar semua hal yang aku gumamkan pada diri sendiri?!",
  ui_story_31650601_97_dialog_content = "Dia memiliki kekuatan psikis, Ciel. Jangan lupa itu.",
  ui_story_31650601_98_dialog_content = "Bahkan dengan kemampuan psikis, mungkin aku tidak bisa menemukan posisi Ciel melalui es tebal jika dia tidak bergumam.",
  ui_story_31650601_99_dialog_content = "Jadi itu berarti kamu juga mendengar itu, PlayerName...",
  ui_story_31650601_100_dialog_content = "Apa? Apakah kamu mengatakan sesuatu yang tidak ingin PlayerName dengar, Ciel?",
  ui_story_31650601_101_dialog_content = "Tidak, saya tidak melakukannya! Terima kasih atas usaha Anda menyelamatkan saya, Petugas Gronru, PlayerName!",
  ui_story_31650601_102_dialog_content = "Sekarang saya harus membawa tim kembali ke jalur yang benar dengan proyek ini!",
  ui_story_31650601_103_dialog_content = "Tenang saja, Ciel, kamu baru saja selamat dengan hidupmu!",
  ui_story_31650601_104_dialog_content = "Apa yang terjadi dengan dia? Lari begitu cepat...",
  ui_story_31650601_105_dialog_content = "Masih tidak mengerti, PlayerName? Jangan mencoba mengerti perempuan. Tentu saja, jangan mencoba mengintip pikiran mereka juga.",
  ui_story_31650601_106_dialog_content = "Hah?",
  ui_story_31650601_107_dialog_content = "... and PlayerName... Will I never see him ever again?",
  ui_story_31650601_108_dialog_content = "Never thought it would end like this... What a bitter pill to swallow.",
  ui_story_31650601_109_dialog_content = "Apa PlayerName benar-benar mendengar itu?",
  ui_story_31650601_110_dialog_content = "Kuharap tidak...",
  ui_story_31650601_111_dialog_content = "Tunggu, tidak, kuharap dia melakukannya..."
}
return config
